INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 0, 'cover', 'Управление инициативами инвестиционного бюджета', 'Роли, ответственность и порядок принятия решений по Мероприятиям и Инициативам', '[{"id": "b1", "kind": "banner", "color": "violet"}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 1, 'roles', 'Ключевые роли управления', 'Кто отвечает за инвестиционный бюджет, мероприятия и инициативы', '[{"id": "b1", "kind": "roles", "roles": [{"icon": "Wallet", "title": "Владелец инвестиционного бюджета", "text": "Работник Банка, ответственный за развитие направления деятельности и организацию реализации Мероприятий. Утверждается Правлением Банка или УКО.", "color": "violet"}, {"icon": "Target", "title": "Ответственный за реализацию инициативы", "text": "Отвечает за достижение основных параметров инициативы, управляет реализацией в рамках сметы затрат.", "color": "blue"}, {"icon": "Flag", "title": "Ответственный за реализацию мероприятия", "text": "Отвечает за реализацию Мероприятия, достижение его Результатов и Количественных показателей. Назначается Правлением Банка (УКО).", "color": "orange"}, {"icon": "ClipboardCheck", "title": "Функциональный заказчик", "text": "Участвует в формировании и подтверждении Бизнес-требований по Инициативам с ИТ-составляющей.", "color": "green"}]}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 2, 'quote', 'Что такое Инициатива', 'Раздел 1 Положения', '[{"id": "b1", "kind": "quote", "text": "Ограниченная во времени и ресурсах деятельность, финансируемая из Инвестиционного бюджета Банка и направленная на достижение Количественных показателей и Результатов Мероприятия (или их части).", "author": "Раздел 1. «Инициатива»"}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 3, 'process', 'Назначение Владельца инвестиционного бюджета', 'П. 3.9.1', '[{"id": "b1", "kind": "steps", "steps": [{"title": "Совместное предложение", "text": "ДАР, ДС и ДП готовят предложение на основании внутренних документов Банка", "color": "blue"}, {"title": "Утверждение", "text": "Правление Банка (или УКО) утверждает Владельца на каждое ПНД (ИНД)", "color": "violet"}, {"title": "Согласование", "text": "Кандидатура согласуется с утверждаемым Владельцем инвестиционного бюджета", "color": "orange"}]}, {"id": "b2", "kind": "text", "text": "Владелец утверждается из числа работников Банка, находящихся в непосредственном подчинении Председателю Банка или его первому заместителю (заместителю)."}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 4, 'roles', 'Ответственность Владельца инвестиционного бюджета', 'П. 3.9.2 — с одним важным исключением', '[{"id": "b1", "kind": "cards", "cards": [{"icon": "CheckCircle2", "title": "Общее правило", "text": "Несёт ответственность за достижение Результатов мероприятий и Контрольных точек", "color": "green", "status": "по умолчанию"}, {"icon": "ShieldOff", "title": "Исключение: «Внутренний контроль и аудит»", "text": "Владелец инвестиционного бюджета по этому направлению НЕ несёт ответственности за достижение Результатов мероприятия", "color": "red", "status": "исключение"}]}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 5, 'content', 'Функции, которые НЕ выполняет Владелец', 'По направлению «Внутренний контроль и аудит» — П. 3.9.5', '[{"id": "b1", "kind": "bullets", "items": ["Принятие решения о распределении и перераспределении Лимитов расходов по мероприятиям и инициативам с учётом приоритетов ПНД (ИНД), согласно Матрице принятия решений", "Организация предоставления ДС и ДАР данных для отчёта о реализации Мероприятий и достижении Контрольных точек, Показателей и Результатов за Финансовый период — эту функцию выполняет Ответственный за реализацию мероприятия"]}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 6, 'process', 'Назначение Ответственного за реализацию мероприятия', 'П. 3.10.1', '[{"id": "b1", "kind": "steps", "steps": [{"title": "Общий порядок", "text": "Решением Правления Банка (или УКО) либо Владельца инвестиционного бюджета — из числа руководителей не ниже уровня «Управление»", "color": "blue"}, {"title": "«Внутренний контроль и аудит»", "text": "Из числа работников БИТ или иных подразделений, НЕ находящихся под кураторством Владельца бюджета этого направления", "color": "red"}]}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 7, 'roles', 'Функциональный заказчик', 'П. 3.11.1 – 3.11.2', '[{"id": "b1", "kind": "cards", "cards": [{"icon": "FileSignature", "title": "Назначение", "text": "Решением Владельца инвестиционного бюджета направления «Внутренний контроль и аудит» — оформляется в СЭД Тезис по шаблону БИТ", "color": "blue"}, {"icon": "ListChecks", "title": "Функции", "text": "Участие в формировании и подтверждении Бизнес-требований в рамках Инициатив с ИТ-составляющей", "color": "violet"}]}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 8, 'content', 'Назначение Ответственного за реализацию инициативы', 'П. 3.12.1', '[{"id": "b1", "kind": "bullets", "items": ["Назначается решением соответствующего Ответственного за реализацию мероприятия", "Решение оформляется в СЭД Тезис по шаблону БИТ, согласуется с непосредственным руководителем"]}, {"id": "b2", "kind": "banner", "color": "orange", "text": "Ответственный за реализацию инициативы НЕ может назначаться из числа работников подразделений направления «Внутренний контроль и аудит»"}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 9, 'content', 'Изменения в Инициативу', 'П. 6.2', '[{"id": "b1", "kind": "text", "text": "Устанавливает порядок внесения изменений в Инициативу. Соответствующие шаблоны есть в СЭД Тезис (например, «Об изменении бюджета проекта»)."}]'::jsonb);
INSERT INTO t_p61016064_digital_innovation_i.biz_slides (presentation_id, order_index, layout, title, subtitle, blocks_json) VALUES (1, 10, 'closing', 'Единая логика управления', 'Каждая роль имеет чёткую зону ответственности — включая особые ограничения для направления «Внутренний контроль и аудит»', '[{"id": "b1", "kind": "metrics", "metrics": [{"value": "4", "label": "ключевые роли"}, {"value": "2", "label": "уровня: мероприятие и инициатива"}, {"value": "1", "label": "особое направление — ВК и аудит"}]}]'::jsonb);
